    "updated_at": "2019-01-01T00:00:00",
    "private": true,
    "like_count": 1,
    "payment_card_digits": "string",
    "comment_count": 1,
    "sender": {
     "name": "string",
     "email": "user@example.com"
    },
    "receiver": {
     "name": "string",
     "email": "user@example.com"
    },
    "liked": true
   }
  ],
  "failure": {
